-- Reconcile the approved four-book source catalog after migrations 001–005.
-- No purchases, subscribers, customers, credentials or sale rights are created.
begin;
alter table public.books add column if not exists kindle_unlimited boolean not null default false;
update public.book_series set description='Historical nonfiction and personal memory, from precolonial roots through colonial rule to independent Zimbabwe. The trilogy comprises Book One, Book Two and Book Three.' where id='10000000-0000-4000-8000-000000000001';
do $$ declare book_key uuid; begin
 insert into public.books(id,slug,title,subtitle,short_description,full_description,genre,series_id,series_position,cover_path,display_order,tone,themes,source_url,featured,status,kindle_unlimited)
 values('20000000-0000-4000-8000-000000000001','4daniel-book-one','4Daniel','A Precolonial History and My Life History in Rhodesia and Zimbabwe','An exploration of precolonial Central and Southern Africa, where historical research meets personal memory.',array['The first book in the 4Daniel series brings archaeological evidence and indigenous oral traditions into conversation with Edmund’s own experiences.','It explores the Great Zimbabwe cultural heritage, Swahili trade and Portuguese involvement in the region, tracing a history that reaches beyond colonial accounts. The series began as a legacy for his son Daniel, who grew up in Germany.'],'History & memoir','10000000-0000-4000-8000-000000000001',1,'/images/4daniel-book-one.jpg',1,'sage',array['Precolonial Africa','Cultural heritage','Personal memory'],'https://www.goodreads.com/book/show/210820405-4daniel',false,'published',true) on conflict(slug) do nothing;
 select id into strict book_key from public.books where slug='4daniel-book-one';
 update public.books set kindle_unlimited=true where id=book_key and kindle_unlimited is distinct from true;
 insert into public.book_drafts(book_id,data) values(book_key,'{"slug":"4daniel-book-one","title":"4Daniel","subtitle":"A Precolonial History and My Life History in Rhodesia and Zimbabwe","short_description":"An exploration of precolonial Central and Southern Africa, where historical research meets personal memory.","full_description":["The first book in the 4Daniel series brings archaeological evidence and indigenous oral traditions into conversation with Edmund’s own experiences.","It explores the Great Zimbabwe cultural heritage, Swahili trade and Portuguese involvement in the region, tracing a history that reaches beyond colonial accounts. The series began as a legacy for his son Daniel, who grew up in Germany."],"genre":"History & memoir","series_id":"10000000-0000-4000-8000-000000000001","series_position":1,"cover_asset_id":"","cover_path":"/images/4daniel-book-one.jpg","publication_date":"","language":"en","featured":false,"display_order":1,"tone":"sage","themes":["Precolonial Africa","Cultural heritage","Personal memory"],"source_url":"https://www.goodreads.com/book/show/210820405-4daniel","seo_title":"","seo_description":""}'::jsonb) on conflict(book_id) do nothing;
 insert into public.book_editions(book_id,format,sale_channel,availability,currency,price_minor)
 values(book_key,'ebook','direct','pending','USD',777)
 on conflict(book_id,format,sale_channel) do update set currency=excluded.currency,price_minor=excluded.price_minor
 where public.book_editions.availability='pending' and not public.book_editions.direct_sale_rights_confirmed;
 insert into public.book_editions(book_id,format,sale_channel,availability,external_purchase_url,external_product_identifier,link_verified)
 values(book_key,'ebook','amazon','available','https://www.amazon.com/dp/B0CZTYLFSG','B0CZTYLFSG',true) on conflict(book_id,format,sale_channel) do nothing;
 insert into public.book_editions(book_id,format,sale_channel,availability,external_purchase_url,external_product_identifier,link_verified)
 values(book_key,'paperback','amazon','available','https://www.amazon.com/dp/B0CYVNQJ4M','B0CYVNQJ4M',true) on conflict(book_id,format,sale_channel) do nothing;
end $$;
do $$ declare book_key uuid; begin
 insert into public.books(id,slug,title,subtitle,short_description,full_description,genre,series_id,series_position,cover_path,display_order,tone,themes,source_url,featured,status,kindle_unlimited)
 values('20000000-0000-4000-8000-000000000002','4daniel-book-two','4Daniel','An African Colonial History and Memoir','The colonial experience of Southern Rhodesia, explored through historical scholarship and lived experience.',array['The second 4Daniel book examines African colonial history, with particular attention to Southern Rhodesia between 1880 and 1980.','Historical analysis is interwoven with memories of growing up in a segregated society and the experiences of early Black students at Peterhouse. Together, these perspectives consider the ways colonial systems shaped education, identity and everyday life.'],'History & memoir','10000000-0000-4000-8000-000000000001',2,'/images/4daniel-book-two.jpg',2,'walnut',array['Colonial history','Education & identity','Lived experience'],'https://www.goodreads.com/book/show/240713691-book-two-4daniel',false,'published',true) on conflict(slug) do nothing;
