 values(book_key,'ebook','amazon','available','https://www.amazon.com/dp/B0FNX7L165','B0FNX7L165',true) on conflict(book_id,format,sale_channel) do nothing;
 insert into public.book_editions(book_id,format,sale_channel,availability,external_purchase_url,external_product_identifier,link_verified)
 values(book_key,'paperback','amazon','available','https://www.amazon.com/dp/B0FQP4FZ58','B0FQP4FZ58',true) on conflict(book_id,format,sale_channel) do nothing;
