 insert into public.book_drafts(book_id,data) values(book_key,'{"slug":"4daniel-book-three","title":"The Shadow of the Beast","subtitle":"An African Neocolonial History","short_description":"The concluding volume of the 4Daniel trilogy examines Zimbabwe’s postcolonial history and the continuing influence of colonial structures.","full_description":["In The Shadow of the Beast, Edmund Katso turns to neocolonial history, completing the 4Daniel trilogy’s passage from precolonial roots through colonial rule to independent Zimbabwe.","The book considers the transition from Rhodesia to Zimbabwe, tracing the author’s argument about enduring connections between political power, security institutions and resource extraction."],"genre":"African history","series_id":"10000000-0000-4000-8000-000000000001","series_position":3,"cover_asset_id":"","cover_path":"/images/4daniel-book-three.jpg","publication_date":"","language":"en","featured":false,"display_order":4,"tone":"walnut","themes":["Neocolonial history","Independent Zimbabwe","Power & resources"],"source_url":"https://www.amazon.co.uk/dp/B0GX2ZY8MF","seo_title":"","seo_description":""}'::jsonb) on conflict(book_id) do nothing;
